bool extract_socket_address_and_port(struct pool *pool, char *url) {
    char *colon = NULL;
    char *address = url;
    int port = 0;
    int address_length = 0;
    char address_buffer[NI_MAXHOST];

    // Check if URL is valid
    if (url == NULL || *url == '\0') {
        return false;
    }

    // Check for IPv6 address (enclosed in [])
    if (*url == '[') {
        char *closing_bracket = strchr(url + 1, ']');
        if (closing_bracket == NULL) {
            return false;
        }

        address = url + 1;
        colon = strchr(closing_bracket + 1, ':');
    } else {
        colon = strchr(url, ':');
    }

    // If port is present
    if (colon != NULL) {
        *colon = '\0';
        port = atoi(colon + 1);
        *colon = ':';
    }

    // Set default port if not specified
    if (port == 0) {
        port = 80;
    }

    // Truncate the address if it is too long
    address_length = strlen(address);
    if (address_length >= sizeof(address_buffer)) {
        address_length = sizeof(address_buffer) - 1;
    }

    memcpy(address_buffer, address, address_length);
    address_buffer[address_length] = '\0';

    // Update the pool structure
    strncpy(pool->socket_address, address_buffer, sizeof(pool->socket_address) - 1);
    pool->socket_port = port;

    return true;
}

