bool extract_socket_info_from_url(struct pool *pool, char *url) {
    char *start, *end, *colon;
    char address[NI_MAXHOST];
    int port;
    bool success = false;

    if (url == NULL || *url == '\0') {
        return false;
    }

    start = url;
    // Check for IPv6 address in brackets
    if (*start == '[') {
        start++;
        end = strchr(start, ']');
        if (end == NULL) {
            return false;
        }
    } else {
        end = start + strlen(start);
    }

    colon = strchr(start, ':');
    if (colon != NULL && colon < end) {
        // Port is present
        char port_str[6];
        int port_len = (int)(end - colon - 1);
        if (port_len > sizeof(port_str) - 1) {
            port_len = sizeof(port_str) - 1;
        }
        strncpy(port_str, colon + 1, port_len);
        port_str[port_len] = '\0';
        port = atoi(port_str);
    } else {
        port = 80; // Default port
    }

    // Truncate address if necessary
    int address_len = (int)(end - start);
    if (address_len > sizeof(address) - 1) {
        address_len = sizeof(address) - 1;
    }
    strncpy(address, start, address_len);
    address[address_len] = '\0';

    // Store in pool
    pool->socket_address = strdup(address);
    pool->port = port;
    success = true;

    return success;
}

#include <string.h>
