bool extract_address_and_port(struct pool *pool, char *url) {
    char *url_start = url;
    char *colon = NULL;
    char *end_of_address = url;
    int port = -1;
    size_t address_length;
    char address_buffer[1024]; // Assuming a reasonable buffer size for an address
    char *url_end = url + strlen(url);

    // Check for IPv6 address (enclosed in brackets)
    if (*url == '[') {
        url++;
        url_start = url;
        char *closing_bracket = strchr(url, ']');
        if (!closing_bracket || closing_bracket >= url_end) {
            return false;
        }
        end_of_address = closing_bracket;
        url = closing_bracket + 1;
    }

    // Look for colon to determine port
    colon = strchr(url, ':');
    if (colon && colon < url_end) {
        port = atoi(colon + 1);
    }

    // Calculate the address length
    address_length = end_of_address - url_start;
    if (address_length >= sizeof(address_buffer)) {
        address_length = sizeof(address_buffer) - 1;
    }

    // Copy the address into the buffer
    strncpy(address_buffer, url_start, address_length);
    address_buffer[address_length] = '\0';

    // Set default port if none was specified
    if (port == -1) {
        port = 80; // Default HTTP port
    }

    // Update the pool structure with the extracted values
    strncpy(pool->socket_address, address_buffer, sizeof(pool->socket_address) - 1);
    pool->socket_address[sizeof(pool->socket_address) - 1] = '\0'; // Ensure null termination
    pool->port = port;

    return true;
}
